 {['accounts','sub-dealers'].includes(section)&&<section className="panel table-panel" data-tour="accounts-table">{d.account_status_counts&&<StatusTabs counts={d.account_status_counts} filters={filters} section={section} statuses={accountStatuses}/>}<Filter section={section} filters={filters}/><Table searchable={false} totalCount={d.accounts.total} rows={d.accounts.data} columns={[{key:'name',title:translate('portal','col_partner'),render:r=><><b>{r.name}</b>{r.profile?.shop_name&&<span className="cell-sub ptl-shop">🏪 {r.profile.shop_name}</span>}{r.profile?.name_bn&&<span className="cell-sub ptl-name-bn">{r.profile.name_bn}</span>}<small className="cell-sub">{r.phone?`${r.phone} · `:''}{r.email}</small></>},{key:'dealer_code',title:translate('portal','col_dealer_code'),render:r=><b>{r.dealer_code??'—'}</b>},{key:'sponsor',title:translate('portal','net_sponsor'),render:r=>r.sponsor?.name?<>{r.sponsor.name}<small className="cell-sub">{r.sponsor.dealer_code}</small></>:r.profile?.refer_code?<small className="cell-sub">{r.profile.refer_code}</small>:'—'},{key:'place',title:translate('portal','col_place'),render:r=>r.profile?.place_code||r.profile?.area_code||'—'},{key:'role',title:translate('portal','col_type'),render:r=><span className={`badge ${r.role}`}>{label(r.role,translate)}</span>},{key:'district',title:translate('portal','label_location'),render:r=><>{r.district??'—'}{r.division?`, ${r.division}`:''}</>},{key:'joined',title:translate('portal','col_joined'),render:r=>date(r.created_at)},{key:'status',title:translate('portal','col_status'),render:r=><Badge status={r.status}/>},{key:'action',title:translate('portal','col_manage'),render:r=><div className="inline-actions"><button className="text-link" disabled={r.id===u.id||!(staffActions?.accounts?.edit??true)} onClick={()=>open('editAccount',r)}>{translate('portal','edit_status')}</button><button className="text-link" disabled={r.status!=='active'||!(staffActions?.accounts?.edit??true)} onClick={()=>router.post(`/commands/accounts/${r.id}/invite`)}>{translate('portal','send_invitation')}</button></div>}]}/><Pagination page={d.accounts}/></section>}
 {section==='inventory'&&<><div className="toolbar-end ops-row is-wrap"><button type="button" className="button dark" disabled={!(staffActions?.inventory?.create??true)} onClick={()=>open('stock_in')}><Plus size={17}/>{translate('portal','stock_action_product_in')}</button><button type="button" className="button" disabled={!(staffActions?.inventory?.create??true)} onClick={()=>open('stock_out')}>{translate('portal','stock_action_product_out')}</button></div><StockOnHand products={d.products||[]} branchName={d.active_branch?.name||translate('portal','branch_company_wide')} branchCount={d.branches?.length||0} canToggle={staffActions?.inventory?.edit??true} showBranch/><section className="panel"><h2>{translate('portal','movement_history')}</h2><Table printable totalCount={d.movements.total} rows={d.movements.data} columns={[{key:'created_at',title:translate('portal','col_date'),render:r=>dateTime(r.created_at)},{key:'name',title:translate('portal','col_product')},{key:'sku',title:translate('portal','col_sku')},{key:'branch_code',title:translate('portal','col_branch'),render:r=>r.branch_name||r.branch_code||'—'},{key:'quantity',title:translate('portal','col_quantity'),align:'right',render:r=>number(r.quantity)},{key:'kind',title:translate('portal','col_type'),render:r=>label(String(r.kind||''),translate)},{key:'reason',title:translate('portal','inv_col_reason_order')},{key:'actor_name',title:translate('portal','audit_actor'),render:r=>r.actor_name||'—'}]}/><Pagination page={d.movements}/></section></>}
